@dataclass
class ProtocolError:
    code: str
    wire_size: int


@dataclass
class Discarded:
    wire_size: int


class FrameDecoder:
    HEADER = 4
    MAX_BODY = 64

    def __init__(self):
        self._buffer = bytearray()
        self._skip = 0

    def feed(self, data):
        self._buffer.extend(data)
        events = []
        while True:
            if self._skip:
                dropped = min(len(self._buffer), self._skip)
                del self._buffer[:dropped]
                self._skip -= dropped
                if dropped:
                    events.append(Discarded(dropped))
                if self._skip:
                    break
                continue
            if len(self._buffer) < self.HEADER:
                break
            length = struct.unpack("!I", self._buffer[:4])[0]
            if length > self.MAX_BODY:
                del self._buffer[:4]
                self._skip = length
                events.append(ProtocolError("frame-too-large", self.HEADER))
                continue
            if len(self._buffer) < self.HEADER + length:
                break
            raw = bytes(self._buffer[4:4 + length])
            del self._buffer[:4 + length]
            try:
                payload = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, ValueError):
                events.append(ProtocolError("invalid-payload", self.HEADER + length))
            else:
                events.append(Frame(payload, self.HEADER + length))
        return events

